"""
Chunk 7 patch: Groups frontend wiring (App.tsx).

Wires GroupDetailScreen, GroupCreateScreen, the ForumScreen "My Groups" strip,
and a new Groups tab on ExploreScreen to the real backend group endpoints
(/groups, /groups/mine, /groups/:id, join/leave, posts+questions with inline
expand-in-place comments, members, files). No backend changes needed - the
Group/GroupPost/etc. routes already exist in app.py.

This is a full-file, hash-verified replacement of frontend/src/App.tsx rather
than a series of anchor patches, because the diff touches ~600 lines across
four screens in one shared file - a safer approach than dozens of fragile
multi-line anchors given known CRLF/drift risks in this repo.

Run from the frontend/ directory's PARENT (i.e. the repo root, same folder
that contains frontend/src/App.tsx):

    python3 chunk7_groups_patch.py

Then from frontend/:
    npx tsc --noEmit
"""
