def main():
    try:
        with io.open(PATH, encoding="utf-8", newline="") as f:
            current = f.read()
    except FileNotFoundError:
        print(f"ERROR: {PATH} not found. Run this script from the repo root.")
        sys.exit(1)

    uses_crlf = "\r\n" in current
    normalized_current = current.replace("\r\n", "\n")
    actual_hash = hashlib.sha256(normalized_current.encode("utf-8")).hexdigest()

    if actual_hash != EXPECTED_ORIGINAL_SHA256:
        print(
            "ABORTING: frontend/src/App.tsx does not match the expected "
            "pre-patch content.\n"
            f"  expected sha256: {EXPECTED_ORIGINAL_SHA256}\n"
            f"  actual sha256:   {actual_hash}\n"
            "The file has likely changed since this patch was built (a helper-"
            "account commit, or another session's edits). Re-clone, re-verify "
            "with git log/tsc, and ask for a fresh patch rather than forcing "
            "this one."
        )
        sys.exit(1)

    new_content = base64.b64decode(NEW_CONTENT_B64.strip()).decode("utf-8")
    output = new_content.replace("\n", "\r\n") if uses_crlf else new_content

    with io.open(PATH, "w", encoding="utf-8", newline="") as f:
        f.write(output)

    print("Patched frontend/src/App.tsx (Chunk 7: Groups) successfully.")
    print("Next: cd frontend && npx tsc --noEmit")

if __name__ == "__main__":
    main()
